def _scan_files_local(
    roots: list[str],
    exclude: list[str],
    suffixes: list[str],
    needles: list[str],
    *,
    max_files: int,
    max_size: int,
) -> tuple[int, list[dict[str, str]]]:
    blocked = [os.path.abspath(item) for item in exclude]
    found: list[dict[str, str]] = []
    inspected = 0
    for root in roots:
        if not os.path.isdir(root):
            continue
        for dirpath, dirnames, filenames in os.walk(root):
            current = os.path.abspath(dirpath)
            if any(current == item or current.startswith(item + os.sep) for item in blocked):
                dirnames[:] = []
                continue
            for name in filenames:
                inspected += 1
                if inspected > max_files:
                    break
                if suffixes and not name.lower().endswith(tuple(suffixes)):
                    continue
                path = os.path.join(dirpath, name)
                try:
                    if os.path.getsize(path) > max_size:
                        continue
                    with open(path, encoding="utf-8", errors="replace") as handle:
                        text = handle.read()
                except OSError:
                    continue
                low = text.lower()
                if needles and not any(str(item).lower() in low for item in needles):
                    continue
                found.append({"path": path, "text": text[:400000]})
                if len(found) >= 30:
                    break
            if inspected > max_files or len(found) >= 30:
                break
        if inspected > max_files or len(found) >= 30:
            break
    return inspected, found


def _text(value: Any) -> str:
    return "" if value is None else str(value)


def _plain(text: str) -> str:
    return re.sub(r"<[^>]+>", " ", text)


def _roots(params: Mapping[str, Any]) -> list[str]:
    declared = params.get("search_roots")
    found: list[str] = []
    if isinstance(declared, list):
        for item in declared:
            text = str(item or "").strip()
            if text and text not in found:
                found.append(text)
    workspace = str(params.get("workspace_dir") or "").strip()
    if workspace and workspace not in found:
        found.insert(0, workspace)
    for item in DEFAULT_ROOTS:
        if item not in found:
            found.append(item)
    return found


_VOID_TAGS = {"area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "source", "track", "wbr"}
_BOLD_TAGS = {"b", "strong", "th", "h1", "h2", "h3", "h4", "h5", "h6"}


class _Element:
    def __init__(self, tag: str, attrs: Mapping[str, str], parent: "_Element | None") -> None:
        self.tag = tag
        self.attrs = dict(attrs)
        self.parent = parent
        self.children: list[Any] = []

    def style(self, prop: str) -> str:
        for part in _text(self.attrs.get("style")).split(";"):
            name, _, value = part.partition(":")
            if name.strip().lower() == prop:
                return value.strip().lower()
        return ""

    def texts(self) -> list[tuple[str, "_Element"]]:
        found: list[tuple[str, _Element]] = []
        for child in self.children:
            if isinstance(child, _Element):
                found.extend(child.texts())
            elif child.strip():
                found.append((child, self))
        return found

    def iter(self):
        yield self
        for child in self.children:
            if isinstance(child, _Element):
                yield from child.iter()


def _parse_html(text: str) -> _Element:
    from html.parser import HTMLParser

    root = _Element("#root", {}, None)

    class Builder(HTMLParser):
        def __init__(self) -> None:
            super().__init__(convert_charrefs=True)
            self.current = root

        def handle_starttag(self, tag, attrs):
            element = _Element(tag, {k: v or "" for k, v in attrs}, self.current)
            self.current.children.append(element)
            if tag not in _VOID_TAGS:
                self.current = element

        def handle_endtag(self, tag):
            node: _Element | None = self.current
            while node is not None and node.tag != tag:
                node = node.parent
            if node is not None and node.parent is not None:
                self.current = node.parent

        def handle_data(self, data):
            if self.current.tag not in ("style", "script", "title"):
                self.current.children.append(data)

    Builder().feed(text)
    return root


def _is_bold(element: "_Element | None") -> bool:
    # The nearest element that sets a weight decides, as in CSS inheritance: <b>, <strong>,
    # <th> and h1-h6 are bold by default, and an inline font-weight overrides the tag
    # (execCommand("bold") on a bold heading writes font-weight: normal).
    while element is not None:
        weight = element.style("font-weight")
        if weight:
            if weight in ("bold", "bolder"):
                return True
            return weight.isdigit() and int(weight) >= 600
        if element.tag in _BOLD_TAGS:
            return True
        element = element.parent
    return False


def _font_size_14(element: "_Element | None") -> bool:
    # OpenDoc's size list maps "14" to execCommand("fontSize", "4"), exported as <font size="4">.
    while element is not None:
        size = element.style("font-size")
        if size:
            return size.replace(" ", "") in ("14pt", "14px", "large", "18.6667px", "18.67px")
        if element.tag == "font" and element.attrs.get("size"):
            return element.attrs["size"].strip() == "4"
        element = element.parent
    return False


def _heading_runs(text: str, wanted: str) -> list[tuple[str, _Element]]:
    """Text runs of the first h1-h6 element whose text contains ``wanted``."""

    for element in _parse_html(text).iter():
        if element.tag in ("h1", "h2", "h3", "h4", "h5", "h6"):
            runs = element.texts()
            if wanted.lower() in " ".join("".join(run for run, _ in runs).split()).lower():
                return runs
    return []


def _comment_blob(documents: list[dict[str, Any]], title: str) -> str:
    parts: list[str] = []
    for document in documents:
        if title and _text(document.get("title")) != title:
            continue
        comments = document.get("comments")
        if isinstance(comments, list):
            for comment in comments:
                if isinstance(comment, Mapping):
                    parts.append(_text(comment.get("text")))
                    parts.append(_text(comment.get("quote")))
                    parts.append(_text(comment.get("body")))
                else:
                    parts.append(_text(comment))
        parts.append(_text(document.get("html")))
        parts.append(_text(document.get("header")))
        parts.append(_text(document.get("footer")))
    return " ".join(parts).lower()


class OpenDocClientPlanHtmlEvaluator(BaseEvaluator):
    """Verify the exported Client Plan HTML document and its formatting."""

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        controller = context.get("controller")
        checks: list[dict[str, Any]] = []

        def record(name: str, passed: bool, actual: Any) -> None:
            checks.append({"name": name, "passed": bool(passed), "actual": actual})

        required = [_text(item) for item in (params.get("required_html_texts") or [])]
        auxiliary = [_text(item) for item in (params.get("auxiliary_texts") or [])]
        documents, source = _read_documents(controller, params)
        metadata: dict[str, Any] = {"source": source, "document_titles": [d.get("title") for d in documents], "checks": checks}

        inspected, files = _scan_files(
            controller,
            _roots(params),
            [],
            [".html", ".htm"],
            required[:3] or ["client plan"],
            max_files=int(params.get("max_files") or 6000),
            max_size=int(params.get("max_file_size") or 12000000),
            timeout=int(params.get("timeout") or 120) + 30,
        )
        metadata["inspected"] = inspected
        metadata["export_paths"] = [item.get("path") for item in files]

        best: dict[str, str] | None = None
        best_score = -1
        for item in files:
            low = _text(item.get("text")).lower()
            score = sum(1 for text in required if text.lower() in low)
            if score > best_score:
                best = item
                best_score = score
        record("export.file", best is not None, metadata["export_paths"])
        if best is None:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="the Client Plan HTML export was not found under the declared roots",
                metadata=metadata,
            )

        text = _text(best.get("text"))
        low = text.lower()
        metadata["export_path"] = best.get("path")
        for index, wanted in enumerate(required):
            record("html.%d" % index, wanted.lower() in low, wanted)

        blob = low + " " + _comment_blob(documents, "Client Plan")
        for index, wanted in enumerate(auxiliary):
            record("comment.%d" % index, wanted.lower() in blob, wanted)

        structure = {
            "heading": bool(re.search(r"<h[1-6][\s>]", text, re.I)),
            "list": ("<ul" in low) or ("<ol" in low) or ("<li" in low),
            "table": "<table" in low,
            "paragraph": "<p" in low,
            "emphasis": ("<strong" in low) or ("<b>" in low) or ("<b " in low),
        }
        metadata["structure_markers"] = structure
        record(
            "structure_markers",
            sum(1 for value in structure.values() if value) >= int(params.get("structure_markers_minimum") or 0),
            structure,
        )

        # Size and bold are read from the text of the Client Plan heading itself: a substring
        # search matched the export's CSS boilerplate ("margin-bottom: 14px") and took
        # "font-weight: normal" for bold, while missing a heading that is bold by default.
        heading_runs = _heading_runs(text, _text(params.get("heading_text") or (required[0] if required else "Client Plan")))
        metadata["heading_text"] = "".join(run for run, _ in heading_runs)
        formatting = {
            "aptos": "aptos" in low,
            "size14": bool(heading_runs) and all(_font_size_14(element) for _, element in heading_runs),
            "bold": bool(heading_runs) and all(_is_bold(element) for _, element in heading_runs),
            "black": ("#000" in low) or ("black" in low) or ("rgb(0, 0, 0)" in low) or ("rgb(0,0,0)" in low),
            "highlight": ("background-color" in low) or ("<mark" in low) or ("hilitecolor" in low) or ("#fff2a8" in low),
        }
        metadata["format_markers"] = formatting
        record(
            "format_markers",
            sum(1 for value in formatting.values() if value) >= int(params.get("format_markers_minimum") or 0),
            formatting,
        )

        failures = [item["name"] for item in checks if not item["passed"]]
        if failures:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="Client Plan export does not match: %s" % ", ".join(failures[:8]),
                metadata=metadata,
            )
        return EvalResult(status=EvalStatus.PASS, message="Client Plan export matches the declared state", metadata=metadata)


class OpenDocHtmlExportEvaluator(BaseEvaluator):
    """Verify the exported Ops Brief HTML content document."""

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        controller = context.get("controller")
        checks: list[dict[str, Any]] = []

        def record(name: str, passed: bool, actual: Any) -> None:
            checks.append({"name": name, "passed": bool(passed), "actual": actual})

        expected = params.get("expected") if isinstance(params.get("expected"), Mapping) else {}
        identifying = [_text(item) for item in (expected.get("export_identifying_texts") or [])]
        required = [_text(item) for item in (expected.get("required_texts") or [])]
        suffixes = [_text(item) for item in (expected.get("export_suffixes") or [".html", ".htm", ".doc"])]
        exclude = [_text(item) for item in (params.get("exclude_roots") or [])]
        documents, source = _read_documents(controller, params)
        metadata: dict[str, Any] = {"source": source, "document_titles": [d.get("title") for d in documents], "checks": checks}

        inspected, files = _scan_files(
            controller,
            _roots(params),
            exclude,
            suffixes,
            identifying[:4] or ["ops brief"],
            max_files=int(params.get("max_files") or 6000),
            max_size=int(params.get("max_file_size") or 12000000),
            timeout=int(params.get("timeout") or 120) + 30,
        )
        metadata["inspected"] = inspected
        metadata["export_paths"] = [item.get("path") for item in files]

        best: dict[str, str] | None = None
        best_score = -1
        for item in files:
            low = _text(item.get("text")).lower()
            score = sum(1 for text in identifying if text.lower() in low)
            if score > best_score:
                best = item
                best_score = score
        record("export.file", best is not None, metadata["export_paths"])
        record("export.score", best_score >= int(expected.get("export_min_score") or 0), best_score)
        if best is None or best_score < int(expected.get("export_min_score") or 0):
            return EvalResult(
                status=EvalStatus.FAIL,
                message="the Ops Brief HTML export was not found under the declared roots",
                metadata=metadata,
            )

        text = _text(best.get("text"))
        low = text.lower()
        plain = _plain(text)
        plain_low = plain.lower()
        metadata["export_path"] = best.get("path")

        for index, wanted in enumerate(required):
            record("text.%d" % index, wanted.lower() in low, wanted)

        if expected.get("require_table_markup"):
            record("markup.table", "<table" in low, "<table")
        if expected.get("require_list_markup"):
            record("markup.list", ("<ul" in low) or ("<ol" in low) or ("<li" in low), "<ul/<ol/<li")
        if expected.get("require_heading_markup"):
            record("markup.heading", bool(re.search(r"<h[1-6][\s>]", text, re.I)), "<h1..h6")

        for index, spec in enumerate(expected.get("heading_checks") or []):
            if not isinstance(spec, Mapping):
                continue
            wanted = _text(spec.get("text"))
            levels = [int(level) for level in (spec.get("levels") or []) if str(level).isdigit()]
            found = any(re.search(r"<h%d[^>]*>[^<]*%s" % (level, re.escape(wanted)), text, re.I) for level in levels)
            record("heading.%d" % index, found, wanted)

        for index, item in enumerate(expected.get("list_items") or []):
            wanted = _text(item)
            found = bool(re.search(r"<li[^>]*>[^<]*%s" % re.escape(wanted), text, re.I))
            record("list.%d" % index, found, wanted)

        sequence = [_text(item) for item in (expected.get("table_sequence") or [])]
        table_match = re.search(r"<table[\s\S]*?</table>", text, re.I)
        table_plain = _plain(table_match.group(0)).lower() if table_match else plain_low
        positions = [table_plain.find(item.lower()) for item in sequence]
        record("table_sequence", all(position >= 0 for position in positions) and positions == sorted(positions), dict(zip(sequence, positions)))

        for index, spec in enumerate(expected.get("sequence_checks") or []):
            if not isinstance(spec, Mapping):
                continue
            items = [_text(item) for item in (spec.get("items") or [])]
            positions = [plain_low.find(item.lower()) for item in items]
            record(
                "sequence.%d" % index,
                all(position >= 0 for position in positions) and positions == sorted(positions),
                dict(zip(items, positions)),
            )

        if expected.get("require_font_family_arial"):
            record("font.arial", "arial" in low, "arial")
        if expected.get("require_font_size_12"):
            record("font.size12", ("12pt" in low) or ("12px" in low) or ('size="3"' in low) or ("font-size: 12" in low) or ("font-size:12" in low), "12")

        color_check = _text(expected.get("color_check"))
        if color_check:
            record("color", (color_check.lower() in low) or ("#1f2937" in low) or ("#111827" in low) or ("rgb(0, 0, 0)" in low), color_check)

        comment = _text(expected.get("comment_text"))
        if comment:
            blob = low + " " + _comment_blob(documents, _text(expected.get("title")))
            record("comment", comment.lower() in blob, comment)

        failures = [item["name"] for item in checks if not item["passed"]]
        if failures:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="Ops Brief export does not match: %s" % ", ".join(failures[:8]),
                metadata=metadata,
            )
        return EvalResult(status=EvalStatus.PASS, message="Ops Brief export matches the declared state", metadata=metadata)


class OpenDocLaunchReviewEvaluator(BaseEvaluator):
    """Verify the duplicated Launch Review document and its exports."""

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        controller = context.get("controller")
        checks: list[dict[str, Any]] = []

        def record(name: str, passed: bool, actual: Any) -> None:
            checks.append({"name": name, "passed": bool(passed), "actual": actual})

        expected_texts = [_text(item) for item in (params.get("expected_texts") or [])]
        title = next((item for item in expected_texts if item.lower() == "launch review"), expected_texts[0] if expected_texts else "")
        documents, source = _read_documents(controller, params)
        metadata: dict[str, Any] = {"source": source, "document_titles": [d.get("title") for d in documents], "checks": checks}

        candidates = [document for document in documents if _text(document.get("title")) == title]
        record("document", bool(candidates), [d.get("title") for d in documents])
        if not candidates:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="the %s document was not found in Local Storage" % title,
                metadata=metadata,
            )

        document = candidates[0]
        blob_parts = [
            _text(document.get("title")),
            _text(document.get("html")),
            _text(document.get("header")),
            _text(document.get("footer")),
        ]
        comments = document.get("comments")
        resolved = 0
        comment_rows: list[dict[str, Any]] = []
        if isinstance(comments, list):
            for comment in comments:
                if isinstance(comment, Mapping):
                    blob_parts.append(_text(comment.get("text")))
                    comment_rows.append({"text": _text(comment.get("text")), "resolved": bool(comment.get("resolved"))})
                    if comment.get("resolved"):
                        resolved += 1
        blob = " ".join(blob_parts)
        blob_low = blob.lower()
        for index, wanted in enumerate(expected_texts):
            record("text.%d" % index, wanted.lower() in blob_low, wanted)

        # OpenDoc keeps a resolved comment in the document with resolved: true (the Resolve button
        # toggles the flag), so "resolve this specific comment" is graded on that comment itself.
        resolved_text = " ".join(_text(params.get("resolved_comment_text")).split()).lower()
        if resolved_text:
            record(
                "comment.resolved_text",
                any(
                    row["resolved"] and " ".join(row["text"].split()).lower() == resolved_text
                    for row in comment_rows
                ),
                comment_rows,
            )

        inspected, files = _scan_files(
            controller,
            _roots(params),
            [],
            [".txt", ".doc", ".html", ".htm"],
            ["launch review"],
            max_files=int(params.get("max_files") or 5000),
            max_size=int(params.get("max_file_size") or 12000000),
            timeout=int(params.get("timeout") or 120) + 30,
        )
        metadata["inspected"] = inspected
        metadata["export_paths"] = [item.get("path") for item in files]
        plain_export = any(
            _text(item.get("path")).lower().endswith(".txt") and "launch review" in _text(item.get("text")).lower()
            for item in files
        )
        word_export = any(
            _text(item.get("path")).lower().endswith(".doc") and "launch review" in _text(item.get("text")).lower()
            for item in files
        )
        record("export.plain_text", plain_export, metadata["export_paths"])
        record("export.word", word_export, metadata["export_paths"])

        settings = document.get("settings") if isinstance(document.get("settings"), Mapping) else {}
        html_low = _text(document.get("html")).lower()
        workflow = {
            "toc": ("toc" in html_low) or ("table of contents" in html_low),
            "page_number": ("page" in html_low) or ("page-number" in html_low),
            "date": bool(re.search(r"\b\d{4}-\d{2}-\d{2}\b", html_low)) or ("2026" in html_low),
            "comment_resolved": resolved > 0,
            "ruler": bool(settings.get("ruler")),
        }
        metadata["workflow_markers"] = workflow
        record(
            "workflow_markers",
            sum(1 for value in workflow.values() if value) >= int(params.get("workflow_markers_minimum") or 0),
            workflow,
        )

        failures = [item["name"] for item in checks if not item["passed"]]
        if failures:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="Launch Review document does not match: %s" % ", ".join(failures[:8]),
                metadata=metadata,
            )
        return EvalResult(status=EvalStatus.PASS, message="Launch Review document matches the declared state", metadata=metadata)
